#!/bin/bash -e

# The version file is generated by image/build.sh in the copied stage. It is
# the single source of truth for the package version installed below and for
# the build-info written after the install.
install -D -m 0644 files/etc/weather-pi/image-version \
	"${ROOTFS_DIR}/etc/weather-pi/image-version"

# Enable SPI without duplicating the overlay parameter. Raspberry Pi OS uses
# /boot/firmware for the boot partition on trixie; keep /boot as a fallback for
# older layouts. Appending a fresh [all] section makes the setting independent
# of the conditional section that happened to be last in config.txt.
config=""
for candidate in \
	"${ROOTFS_DIR}/boot/firmware/config.txt" \
	"${ROOTFS_DIR}/boot/config.txt"; do
	if [[ -f "$candidate" ]]; then
		config="$candidate"
		break
	fi
done

if [[ -z "$config" ]]; then
	echo "20-packages: no config.txt under the boot partition" >&2
	exit 1
fi

if ! grep -qE '^[[:space:]]*dtparam=spi=on[[:space:]]*$' "$config"; then
	printf '\n[all]\ndtparam=spi=on\n' >>"$config"
fi

grep -qE '^[[:space:]]*dtparam=spi=on[[:space:]]*$' "$config" || {
	echo "20-packages: failed to enable SPI in $config" >&2
	exit 1
}
